<script setup lang="ts">
import {money} from '~/shared/types'
import type {OrderStatus} from '~/shared/types'
const api=useApi(),busy=ref(''),message=ref(''),actionError=ref('')
const {data:orders,pending,error,refresh}=await useAsyncData('admin-orders',()=>api.orders())
const statuses:Record<OrderStatus,string>={demo_created:'Создан (тест)',demo_processing:'В обработке (тест)',demo_completed:'Завершён (тест)',demo_cancelled:'Отменён (тест)'}
async function update(id:string,event:Event){busy.value=id;actionError.value='';message.value='';try{await api.updateOrder(id,(event.target as HTMLSelectElement).value as OrderStatus);await refresh();message.value='Тестовый статус обновлён.'}catch(e){actionError.value=errorMessage(e);await refresh()}finally{busy.value=''}}
useSeoMeta({title:'Тестовые заказы — Deadlock Family'})
</script>
<template><AdminShell title="Тестовые заказы"><p v-if="message" class="notice success" style="margin-bottom:20px" role="status">{{message}}</p><p v-if="actionError" class="notice error" role="alert">{{actionError}}</p><ApiState :pending="pending" :error="error" :empty="!orders?.length" message="В архиве ещё нет тестовых заказов" @retry="refresh()"><NuxtLink to="/shop" class="btn">Пройти сценарий покупателя</NuxtLink></ApiState><div class="admin-orders"><article v-for="order in orders" :key="order.id" class="form-panel"><div class="admin-order-head"><div><h2 style="margin:0">{{order.number}}</h2><small style="color:var(--muted)">{{new Date(order.createdAt).toLocaleString('ru-RU')}} · {{order.delivery==='pickup'?'Тестовый самовывоз':'Тестовый курьер'}}</small></div><select :value="order.status" class="filter-select" :aria-label="`Статус заказа ${order.number}`" :disabled="busy===order.id" @change="update(order.id,$event)"><option v-for="(label,status) in statuses" :key="status" :value="status">{{label}}</option></select></div><div class="order-items"><div v-for="line in order.items" :key="line.variantId" class="order-line"><span>{{line.name}}<small>{{line.variantLabel}} · {{line.quantity}} шт.</small></span><span>{{money(line.price*line.quantity)}}</span></div></div><div class="summary-row"><span>Демо-доставка</span><span>{{money(order.shipping)}}</span></div><div class="summary-total" style="margin-bottom:0"><span>Тестовый итог</span><span>{{money(order.total)}}</span></div></article></div></AdminShell></template>
